.ann-def .ann-dk { font-size: 10.5px; color: var(--dim); }
.ann-def .ann-dv { font-size: 10.5px; font-weight: 700; color: var(--ink); text-align: right; }

.ann-stat { width: 150px; text-align: left; border-radius: 11px; padding: 13px 15px; background: linear-gradient(160deg,rgba(var(--ann-p-rgb),.13),rgba(var(--ann-p-rgb),.03)); border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-left: 3px solid var(--ann-p); }
.ann-stat .ann-slb { font-size: 9px; font-weight: 800; letter-spacing: 0.1em; color: var(--muted); text-transform: uppercase; }
.ann-stat .ann-snum { font-size: 30px; font-weight: 800; line-height: 1.1; color: var(--ink); font-variant-numeric: tabular-nums; }
.ann-stat .ann-sfoot { font-size: 10px; font-weight: 800; color: var(--ann-p); margin-top: 2px; }
.ann-stat .ann-sfoot::before { content: "▲"; font-size: 8px; }

.ann-metabar { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; width: 238px; justify-content: center; font-size: 10px; color: var(--muted); }
.ann-metabar .ann-mba { display: inline-flex; align-items: center; gap: 5px; font-weight: 700; color: var(--ink); }
.ann-metabar .ann-mav { width: 16px; height: 16px; border-radius: 50%; font-size: 8px; font-weight: 800; display: grid; place-items: center; color: rgb(6, 18, 31); background: var(--ann-a); }
.ann-metabar .ann-sep { color: var(--dim); }
.ann-metabar .ann-mbt { padding: 1px 7px; border-radius: 999px; font-size: 9px; font-weight: 700; color: var(--ann-i); background: rgba(var(--ann-i-rgb),.12); border: 1px solid rgba(var(--ann-i-rgb),.35); }

.ann-updated { display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px; border-radius: 999px; font-size: 10px; color: var(--muted); background: var(--panel2,rgba(255,255,255,.03)); border: 1px solid var(--line); }
.ann-updated .ann-udot { width: 7px; height: 7px; border-radius: 50%; background: var(--ann-p); position: relative; }
.ann-updated .ann-udot::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; border: 1px solid var(--ann-p); animation: 2s ease-out 0s infinite normal none running annLive; }
.ann-updated b { color: var(--ink); font-weight: 700; }
@keyframes annLive { 
  0% { transform: scale(0.6); opacity: 0.9; }
  100% { transform: scale(2.1); opacity: 0; }
}

.ann-attr { display: flex; align-items: center; gap: 9px; width: 210px; text-align: left; padding: 7px 10px; border-radius: 9px; background: var(--panel2,rgba(255,255,255,.02)); border: 1px solid var(--line); }
.ann-attr .ann-aav { flex: 0 0 auto; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 800; color: rgb(6, 18, 31); background: linear-gradient(135deg,var(--ann-i),var(--ann-c)); }
.ann-attr .ann-an { font-size: 11px; font-weight: 700; color: var(--ink); }
.ann-attr .ann-ar { font-size: 9px; color: var(--dim); }

.ann-cite { font-size: 11px; line-height: 1.5; color: var(--muted); width: 220px; text-align: left; }
.ann-cite .ann-cm { display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0px 3px; vertical-align: baseline; font-size: 9px; font-weight: 800; border-radius: 4px; color: var(--ann-c); background: rgba(var(--ann-c-rgb),.15); border: 1px solid rgba(var(--ann-c-rgb),.4); cursor: pointer; }
.ann-cite .ann-cref { display: block; margin-top: 8px; padding-top: 7px; border-top: 1px dashed var(--line); font-size: 9px; color: var(--dim); }
.ann-cite .ann-cref b { color: var(--ann-c); }
